'use strict';

// MODULES //

var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Evaluates the Gaussian Error Linear Unit (GELU) activation function.
*
* @param {number} x - input value
* @returns {number} evaluated GELU
*
* @example
* var v = gelu( 0.0 );
* // returns 0.0
*
* @example
* var v = gelu( 1.0 );
* // returns ~0.8413
*
* @example
* var v = gelu( -Infinity );
* // returns -0.0
*
* @example
* var v = gelu( Infinity );
* // returns Infinity
*
* @example
* var v = gelu( NaN );
* // returns NaN
*/
function gelu( x ) {
	if ( isnan( x ) ) {
		return NaN;
	}
	if ( x === NINF ) {
		return -0.0;
	}
	return 0.5 * x * erfc( -x / SQRT2 );
}


// EXPORTS //

module.exports = gelu;
